#!/usr/bin/env python3
"""Prepare frozen datasets generated by the pinned, unmodified NIST GenVal. Never invent expected outputs."""
import collections,hashlib,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
BASE=ROOT/'src/test/resources/nist-acvp'
def main():
    original=BASE/'generated-aes256/internalProjection.json'
    data=json.loads(original.read_text())
    groups=data['testGroups'];counts=collections.Counter();seen=set()
    for g in groups:
        assert g['keyLen']==256 and g['ivLen']==96 and g['tagLen']==128
        for tc in g['tests']:
            identity=(g['direction'],tc['key'],tc['iv'],tc['aad'],tc.get('pt',''),tc['ct'],tc['tag'],tc.get('testPassed',True))
            if identity in seen:raise ValueError('Duplicate generated vector; investigate before selecting')
            seen.add(identity)
            counts[g['direction']+('_positive' if tc.get('testPassed',True) else '_negative')]+=1
    # Preserve complete NIST generation output; no outcome-based selection or rewriting.
    (BASE/'aes-gcm-sample.json').write_bytes(original.read_bytes())
    files=[BASE/'aes-gcm-sample.json', BASE/'upstream/NIST-NOTICE.txt']
    for name in ['generated-aes256','generated-kts-sha256']:
        files+=sorted(p for p in (BASE/name).iterdir() if p.is_file())
    manifest={'dataset':'Exact package configuration: AES-256-GCM and KTS-OAEP SHA-256','source_repository':'https://github.com/usnistgov/ACVP-Server','commit':'975de31eb83d87039ec88934fdc47d8c312b892d','provenance':'Generated locally with unmodified NIST GenVal, not pre-existing GitHub samples or official NIST certification','selection':'All 120 generated AES cases and 20 KTS basic cases; no cases dropped by outcome','quality':{'aes_cases':sum(counts.values()),'aes_counts':dict(counts),'duplicate_cases':0,'kts_cases':20,'kts_configuration':'RSA-2048, SHA-256/MGF1-SHA-256, empty label, 256-bit keying material'},'license_notice':'upstream/NIST-NOTICE.txt (original notice unchanged)','train_test':'Not applicable: no model training','files':[{'name':str(p.relative_to(BASE)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'size_bytes':p.stat().st_size} for p in files]}
    (BASE/'manifest.json').write_text(json.dumps(manifest,indent=2)+'\n')
    print(json.dumps(manifest['quality'],indent=2))
if __name__=='__main__':main()
